  check('licença já decidida: 409', (await call(hr, 'POST', `/edu/rh/licencas/${lic.json.id}/decidir`, { aprovar: false, motivo: 'tardio' })).status === 409)
  const licC = await call(coord, 'GET', '/edu/rh/licencas')
  check('gestor não vê o tipo de licença de saúde', licC.json.items.every((l: any) => l.tipo !== 'MATERNIDADE' && l.tipo !== 'MEDICA'))
  const ex1 = await call(hr, 'POST', '/edu/rh/exames', { colaboradorId: id1, tipo: 'ADMISSIONAL', realizadoEm: '2025-06-10T12:00:00Z', resultado: 'APTO', medico: 'Dr. Saúde' })
  check('ASO realizado: validade de 12 meses', ex1.status === 201 && ex1.json.venceEm.startsWith('2026-06-10') && ex1.json.situacao === 'VENCIDO', ex1.json)
  check('resultado sem data: 422', (await call(hr, 'POST', '/edu/rh/exames', { colaboradorId: id2, tipo: 'PERIODICO', resultado: 'APTO' })).status === 422)
  const exAg = await call(hr, 'POST', '/edu/rh/exames', { colaboradorId: id2, tipo: 'PERIODICO', agendadoPara: '2026-12-01T12:00:00Z' })
  check('exame agendado', exAg.json.status === 'AGENDADO')
  check('restrição exige descrição', (await call(hr, 'POST', `/edu/rh/exames/${exAg.json.id}/resultado`, { realizadoEm: '2026-10-20T12:00:00Z', resultado: 'APTO_COM_RESTRICAO' })).status === 422)
  const exRes = await call(hr, 'POST', `/edu/rh/exames/${exAg.json.id}/resultado`, { realizadoEm: '2026-10-20T12:00:00Z', resultado: 'APTO_COM_RESTRICAO', restricoes: 'Sem trabalho em altura' })
  check('resultado com restrição cifrado e vencimento', exRes.json.restricoes === 'Sem trabalho em altura' && exRes.json.venceEm.startsWith('2027-10-20') && !!(await prisma.rheExame.findUnique({ where: { id: exAg.json.id } }))?.restricoesCifradas?.startsWith('v1:'))
  const exG = await call(coord, 'GET', `/edu/rh/exames?colaboradorId=${id1}`)
  check('gestor vê a situação do exame sem o resultado', exG.json.items[0].resultado === undefined && exG.json.items[0].situacao === 'VENCIDO')
  const venc = await call(hr, 'GET', '/edu/rh/exames/vencimentos?dias=60')
  check('vencimentos de exame: vencido e ausentes', venc.json.items.some((x: any) => x.colaboradorId === id1 && x.situacao === 'VENCIDO') && venc.json.items.some((x: any) => x.colaboradorId === id3 && x.situacao === 'SEM_EXAME'))
  check('exames só RH para escrever', (await call(coord, 'POST', '/edu/rh/exames', { colaboradorId: id1, tipo: 'PERIODICO' })).status === 403)
  check('outro tenant não vê exames', (await call(hrB, 'GET', '/edu/rh/exames')).json.total === 0)

  secao('Ponto: marcações, ajustes, espelho e fechamento')
  const marcas: any[] = []
  const pushDay = (cid: string, dia: string, e = '08:00', s = '17:00', manual?: any[]) => (manual ?? dayMarks(dia, e, s)).forEach((m) => marcas.push({ colaboradorId: cid, tipo: m.tipo, dataHora: m.dataHora.toISOString() }))
  const diasMarco = Array.from({ length: 31 }, (_, i) => `2026-03-${String(i + 1).padStart(2, '0')}`)
  const dow = (d: string) => new Date(d + 'T12:00:00Z').getUTCDay()
  for (const d of diasMarco) {
    if (dow(d) >= 1 && dow(d) <= 5 && !['2026-03-02', '2026-03-03', '2026-03-05', '2026-03-10', '2026-03-12'].includes(d)) pushDay(id1, d)
  }
  pushDay(id1, '2026-03-02', '08:00', '19:00'); pushDay(id1, '2026-03-03', '08:30', '17:00')
  pushDay(id1, '2026-03-07', undefined, undefined, [M('2026-03-07', '09:00', 'ENTRADA'), M('2026-03-07', '13:00', 'SAIDA')])
  pushDay(id1, '2026-03-08', undefined, undefined, [M('2026-03-08', '09:00', 'ENTRADA'), M('2026-03-08', '11:00', 'SAIDA')])
  for (const d of diasMarco) {
    const w = dow(d)
    if (w >= 1 && w <= 5) pushDay(id2, d, '08:00', d === '2026-03-02' ? '19:00' : d === '2026-03-03' ? '18:00' : '17:00')
    else if (w === 6) pushDay(id2, d, undefined, undefined, [M(d, '08:00', 'ENTRADA'), M(d, '12:00', 'SAIDA')])
  }
  pushDay(id2, '2026-03-15', undefined, undefined, [M('2026-03-15', '09:00', 'ENTRADA'), M('2026-03-15', '13:00', 'SAIDA')])
  // Beatriz teve atestado de 20 dias a partir de 16/03 (afastamento): abonado no ponto
  const imp = await call(hr, 'POST', '/edu/rh/ponto/importar', { marcacoes: [...marcas, { matricula: 'NAO-EXISTE', tipo: 'ENTRADA', dataHora: '2026-03-02T11:00:00Z' }] })
  check('importação de ponto: importadas e rejeitadas', imp.status === 201 && imp.json.importadas === marcas.length && imp.json.rejeitadas.length === 1, { i: imp.json.importadas, n: marcas.length, r: imp.json.rejeitadas })
  const imp2 = await call(hr, 'POST', '/edu/rh/ponto/importar', { marcacoes: marcas.slice(0, 3) })
  check('importação duplicada é rejeitada', imp2.json.importadas === 0 && imp2.json.rejeitadas.length === 3)
  check('importação só pelo RH', (await call(coord, 'POST', '/edu/rh/ponto/importar', { marcacoes: marcas.slice(0, 1) })).status === 403)
  const origs = await prisma.rheMarcacao.groupBy({ by: ['origem'], where: { tenantId: T }, _count: true })
  check('origem IMPORTACAO registrada', origs.some((o) => o.origem === 'IMPORTACAO'))
  // ajustes
  const aj1 = await call(u1, 'POST', '/edu/rh/ponto/ajustes', { data: '2026-03-12', tipo: 'INCLUIR_MARCACOES', marcacoes: [{ tipo: 'ENTRADA', hora: '08:00' }, { tipo: 'SAIDA_INTERVALO', hora: '12:00' }, { tipo: 'RETORNO_INTERVALO', hora: '13:00' }, { tipo: 'SAIDA', hora: '17:00' }], justificativa: 'Esqueci de registrar o ponto neste dia' })
  check('colaborador solicita ajuste', aj1.status === 201 && aj1.json.status === 'PENDENTE')
  check('ajuste exige justificativa', (await call(u1, 'POST', '/edu/rh/ponto/ajustes', { data: '2026-03-12', tipo: 'ABONO_FALTA', justificativa: 'curto' })).status === 400)
  check('ajuste de data futura: 422', (await call(u1, 'POST', '/edu/rh/ponto/ajustes', { data: '2099-01-01', tipo: 'ABONO_FALTA', justificativa: 'justificativa longa o bastante' })).status === 422)
  check('ajuste para outro colaborador: 403', (await call(u1, 'POST', '/edu/rh/ponto/ajustes', { colaboradorId: id2, data: '2026-03-12', tipo: 'ABONO_FALTA', justificativa: 'justificativa longa o bastante' })).status === 403)
  check('não aprova o próprio ajuste', (await call(u1, 'POST', `/edu/rh/ponto/ajustes/${aj1.json.id}/decidir`, { aprovar: true, motivo: 'eu mesmo' })).status === 403)
  check('gestor lista ajustes da equipe', (await call(coord, 'GET', '/edu/rh/ponto/ajustes?status=PENDENTE')).json.items.length === 1)
  check('colaborador de outra equipe não decide', (await call(u2, 'POST', `/edu/rh/ponto/ajustes/${aj1.json.id}/decidir`, { aprovar: true, motivo: 'tentando aprovar' })).status === 403)
  const aprov = await call(coord, 'POST', `/edu/rh/ponto/ajustes/${aj1.json.id}/decidir`, { aprovar: true, motivo: 'conferido com a portaria' })
  check('gestor aprova ajuste e cria marcações', aprov.json.status === 'APROVADO' && (await prisma.rheMarcacao.count({ where: { ajusteId: aj1.json.id, origem: 'AJUSTE' } })) === 4)
  check('ajuste já decidido: 409', (await call(coord, 'POST', `/edu/rh/ponto/ajustes/${aj1.json.id}/decidir`, { aprovar: false, motivo: 'tarde demais' })).status === 409)
  const aj2 = await call(u1, 'POST', '/edu/rh/ponto/ajustes', { data: '2026-03-05', tipo: 'ABONO_FALTA', justificativa: 'Falta sem justificativa formal anexada' })
  check('gestor rejeita ajuste', (await call(coord, 'POST', `/edu/rh/ponto/ajustes/${aj2.json.id}/decidir`, { aprovar: false, motivo: 'sem documento' })).json.status === 'REJEITADO')
  // espelho
  const esp = await call(u1, 'GET', '/edu/rh/ponto/espelho?competencia=2026-03')
  const r1 = esp.json.resumo
  check('espelho do próprio colaborador (provisório)', esp.status === 200 && esp.json.fechado === false && esp.json.dias.length === 31)
  check('espelho: HE 50% = 2h (seg) + 4h (sábado) = 360', r1.extra50Min === 360, r1)
  check('espelho: HE 100% = 2h (domingo)', r1.extra100Min === 120, r1)
  check('espelho: atraso de 30 min e 1 falta (ajuste rejeitado)', r1.atrasoMin === 30 && r1.faltas === 1, r1)
  check('espelho: atestado abona 10/03 (480 min)', r1.abonadoMin === 480, r1)
  check('espelho: 26 dias úteis e 5 de DSR', r1.diasUteis === 26 && r1.diasDsr === 5)
  check('outro colaborador não vê espelho alheio', (await call(u2, 'GET', `/edu/rh/ponto/espelho?colaboradorId=${id1}&competencia=2026-03`)).status === 403)
  check('gestor vê espelho da equipe', (await call(coord, 'GET', `/edu/rh/ponto/espelho?colaboradorId=${id1}&competencia=2026-03`)).status === 200)
  check('competência inválida: 400', (await call(hr, 'GET', `/edu/rh/ponto/espelho?colaboradorId=${id1}&competencia=2026-13`)).status === 400)
  // marcação em tempo real
  const m1 = await call(u1, 'POST', '/edu/rh/ponto/marcar', { origem: 'APP' })
  check('marcação web/app: primeira é ENTRADA', m1.status === 201 && m1.json.tipo === 'ENTRADA' && m1.json.proximo === 'SAIDA_INTERVALO')
  check('marcação duplicada em < 1 min: 429', (await call(u1, 'POST', '/edu/rh/ponto/marcar', {})).status === 429)
  check('ponto de hoje', (await call(u1, 'GET', '/edu/rh/ponto/hoje')).json.marcacoes.length === 1)
  check('PJ não registra ponto', (await prisma.rheColaborador.update({ where: { id: id5 }, data: { userId: (await t1.mk('STAFF')).id } })) && true)
  const pjUser = (await prisma.rheColaborador.findUnique({ where: { id: id5 } }))!.userId!
  const jwt = (await import('jsonwebtoken')).default
  const pjTok = { id: pjUser, role: 'STAFF', tenantId: T, token: jwt.sign({ id: pjUser, email: 'pj@x.com', clinicId: t1.clinic.id, tenantId: T, role: 'STAFF' }, process.env.JWT_SECRET!) } as Actor
  check('PJ recebe 409 ao marcar ponto', (await call(pjTok, 'POST', '/edu/rh/ponto/marcar', {})).status === 409)
  check('marcações próprias sem ipHash exposto', !JSON.stringify((await call(u1, 'GET', '/edu/rh/ponto/marcacoes')).json).includes('ipHash'))
  await prisma.rheMarcacao.deleteMany({ where: { id: m1.json.id } })
  // fechamento
  check('fechamento só pelo RH', (await call(coord, 'POST', '/edu/rh/ponto/fechamento', { competencia: '2026-03' })).status === 403)
  check('fechamento de competência futura: 422', (await call(hr, 'POST', '/edu/rh/ponto/fechamento', { competencia: '2099-01' })).status === 422)
  const fech = await call(hr, 'POST', '/edu/rh/ponto/fechamento', { competencia: '2026-03' })
  check('fechamento mensal', fech.status === 200 && fech.json.fechados >= 4, fech.json)
  check('refechar sem refazer ignora', (await call(hr, 'POST', '/edu/rh/ponto/fechamento', { competencia: '2026-03', colaboradorId: id1 })).json.ignorados.some((x: any) => x.motivo === 'Já fechado'))
  const esp2 = await call(u1, 'GET', '/edu/rh/ponto/espelho?competencia=2026-03')
  check('espelho fechado congelado', esp2.json.fechado === true && esp2.json.resumo.extra50Min === 360)
  check('ajuste em mês fechado: 409', (await call(u1, 'POST', '/edu/rh/ponto/ajustes', { data: '2026-03-20', tipo: 'ABONO_FALTA', justificativa: 'justificativa longa o bastante' })).status === 409)
  check('importação em mês fechado é rejeitada', (await call(hr, 'POST', '/edu/rh/ponto/importar', { marcacoes: [{ colaboradorId: id1, tipo: 'ENTRADA', dataHora: '2026-03-20T11:00:00Z' }] })).json.rejeitadas[0].motivo === 'Competência fechada')
  const fl = await call(hr, 'GET', '/edu/rh/ponto/fechamentos?competencia=2026-03')
  check('lista de fechamentos', fl.json.items.length >= 4 && fl.json.items.every((i: any) => i.status === 'FECHADO'))
  // banco de horas de Beatriz (jornada 44h com banco)
  const sb = await call(hr, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id2}`)
  const expirou = Date.now() > Date.parse('2026-09-30T23:59:59Z')
  check('banco: 2h + 1h a 50% e 4h a 100% (x2) = 660 min', sb.json.saldoMin === 660 && sb.json.saldo === '11:00', sb.json)
  check('banco: vencimento em 6 meses', sb.json.creditos[0].venceEm === '2026-09-30' && sb.json.vencidoMin === (expirou ? 660 : 0))
  check('banco de quem não usa banco fica zerado', (await call(hr, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id1}`)).json.saldoMin === 0)
  check('colaborador vê o próprio banco', (await call(u2, 'GET', '/edu/rh/banco-horas/saldo')).json.saldoMin === 660)
  check('colaborador não vê banco alheio', (await call(u2, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id1}`)).status === 403)
  check('lançamento de banco só RH', (await call(coord, 'POST', '/edu/rh/banco-horas/lancamentos', { colaboradorId: id2, tipo: 'CREDITO', minutos: 60, observacao: 'tentativa' })).status === 403)
  check('vencimento do banco > 12 meses: 422', (await call(hr, 'POST', '/edu/rh/banco-horas/lancamentos', { colaboradorId: id2, tipo: 'CREDITO', minutos: 60, observacao: 'crédito longo', venceEm: '2030-01-01T00:00:00Z' })).status === 422)
  const cred = await call(hr, 'POST', '/edu/rh/banco-horas/lancamentos', { colaboradorId: id2, tipo: 'CREDITO', minutos: 180, observacao: 'Trabalho no evento institucional' })
  check('crédito manual com vencimento calculado', cred.status === 201 && !!cred.json.venceEm)
  check('compensação sem saldo: 422', (await call(hr, 'POST', '/edu/rh/banco-horas/lancamentos', { colaboradorId: id2, tipo: 'COMPENSACAO', minutos: 9999, observacao: 'folga demais' })).status === 422)
  check('compensação registrada', (await call(hr, 'POST', '/edu/rh/banco-horas/lancamentos', { colaboradorId: id2, tipo: 'COMPENSACAO', minutos: 60, observacao: 'Folga compensada' })).status === 201)
  check('saldo após crédito e compensação = 780', (await call(hr, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id2}`)).json.saldoMin === 780)
  check('saldos gerais do banco (RH)', (await call(hr, 'GET', '/edu/rh/banco-horas/saldos')).json.items.some((i: any) => i.colaboradorId === id2))
  check('vencimentos do banco', (await call(hr, 'GET', '/edu/rh/banco-horas/vencimentos?dias=400')).json.items.some((i: any) => i.colaboradorId === id2))
  // reabrir e refechar
  check('reabrir exige motivo', (await call(hr, 'POST', '/edu/rh/ponto/fechamento/reabrir', { competencia: '2026-03', motivo: 'x' })).status === 400)
  const reab = await call(hr, 'POST', '/edu/rh/ponto/fechamento/reabrir', { competencia: '2026-03', colaboradorId: id2, motivo: 'Conferência do banco de horas' })
  check('reabertura do ponto remove créditos do fechamento', reab.json.reabertos === 1 && (await call(hr, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id2}`)).json.saldoMin === 120)
  await call(hr, 'POST', '/edu/rh/ponto/fechamento', { competencia: '2026-03', colaboradorId: id2 })
  check('refechamento recria o crédito (idempotente)', (await call(hr, 'GET', `/edu/rh/banco-horas/saldo?colaboradorId=${id2}`)).json.saldoMin === 780)

  secao('Férias')
  const gp = await call(hr, 'POST', '/edu/rh/ferias/periodos/gerar', { colaboradorId: id2 })
  check('geração de períodos aquisitivos', gp.status === 200 && gp.json.periodos >= 3, gp.json)
  const pers = (await call(hr, 'GET', `/edu/rh/ferias/periodos?colaboradorId=${id2}`)).json.items
  check('primeiro período vencido (concessivo encerrado)', pers[0].status === 'VENCIDO' && pers[1].status === 'DISPONIVEL' && pers[2].status === 'EM_AQUISICAO', pers.map((p: any) => p.status))
  check('direito de 30 dias', pers[1].diasDireito === 30 && pers[1].saldoDias === 30)
  const al = await call(hr, 'GET', '/edu/rh/ferias/alertas')
  check('alerta de férias vencidas em dobro', al.json.items.some((a: any) => a.colaboradorId === id2 && a.dobra && a.severidade === 'CRITICO'))
  check('gestor vê alertas apenas da equipe', (await call(coord, 'GET', '/edu/rh/ferias/alertas')).json.items.every((a: any) => a.colaboradorId === id1))
  check('colaborador não vê alertas gerais', (await call(u2, 'GET', '/edu/rh/ferias/alertas')).status === 403)
  const per2 = pers[1].id
  const sim = await call(hr, 'GET', `/edu/rh/ferias/simular?colaboradorId=${id2}&dias=30`)
  check('simulação de férias', near(sim.json.ferias, 5000) && near(sim.json.terco, 1666.67, 0.05))
  const pg = (parcelas: any[], extra: any = {}) => call(hr, 'POST', '/edu/rh/ferias/programacoes', { colaboradorId: id2, periodoId: per2, parcelas, ...extra })
  check('férias sem parcela de 14 dias: 422', (await pg([{ inicio: '2026-12-01', dias: 10 }, { inicio: '2027-01-11', dias: 10 }, { inicio: '2027-01-25', dias: 10 }])).status === 422)
  check('parcela menor que 5 dias: 422', (await pg([{ inicio: '2026-12-01', dias: 26 }, { inicio: '2027-01-11', dias: 4 }])).status === 422)
  check('início nos 2 dias antes do DSR: 422', (await pg([{ inicio: '2026-12-04', dias: 20 }], { diasAbono: 10 })).status === 422)
  check('venda acima de 1/3: 400', (await pg([{ inicio: '2026-12-01', dias: 14 }], { diasAbono: 11 })).status === 400)
  check('gozo + venda acima do saldo: 422', (await pg([{ inicio: '2026-12-01', dias: 25 }], { diasAbono: 10 })).status === 422)
  check('início antes do fim do aquisitivo: 422', (await call(hr, 'POST', '/edu/rh/ferias/programacoes', { colaboradorId: id2, periodoId: pers[2].id, parcelas: [{ inicio: '2026-12-01', dias: 14 }] })).status === 422)
  const prog = await pg([{ inicio: '2026-12-01', dias: 14 }, { inicio: '2027-01-11', dias: 6 }], { diasAbono: 10 })
  check('férias fracionadas 14+6 com venda de 10 dias', prog.status === 201 && prog.json.items.length === 2 && prog.json.items[0].diasAbono === 10, prog.json)
  check('valores calculados (RH)', near(prog.json.items[0].valores.ferias, 2333.33, 0.05) && near(prog.json.items[0].valores.abono, 1666.67, 0.05), prog.json.items[0].valores)
  check('saldo do período zerado', (await call(hr, 'GET', `/edu/rh/ferias/periodos?colaboradorId=${id2}`)).json.items[1].saldoDias === 0)
  check('nova programação além do saldo: 422', (await pg([{ inicio: '2027-01-25', dias: 5 }])).status === 422)
  check('sobreposição com férias do colaborador: 409', (await call(hr, 'POST', '/edu/rh/ferias/programacoes', { colaboradorId: id2, periodoId: pers[0].id, parcelas: [{ inicio: '2026-12-02', dias: 14 }] })).status === 409)
  const pid = prog.json.items[0].id
  check('não aprova as próprias férias', (await call(u2, 'POST', `/edu/rh/ferias/programacoes/${pid}/decidir`, { aprovar: true, motivo: 'eu mesma' })).status === 403)
  check('programação visível ao colaborador sem valores', (await call(u2, 'GET', '/edu/rh/ferias/programacoes')).json.items.every((p: any) => p.valores === undefined))
  check('RH aprova férias', (await call(hr, 'POST', `/edu/rh/ferias/programacoes/${pid}/decidir`, { aprovar: true, motivo: 'escala ok' })).json.status === 'APROVADA')
  const cal = await call(coord, 'GET', '/edu/rh/ferias/programacoes')
  check('gestor não vê férias fora da equipe', cal.json.items.every((p: any) => p.colaboradorId === id1))
  check('concluir férias aprovadas atualiza o período', (await call(hr, 'POST', `/edu/rh/ferias/programacoes/${pid}/concluir`, {})).json.status === 'CONCLUIDA' && (await prisma.rheFeriasPeriodo.findUnique({ where: { id: per2 } }))!.diasGozados === 14)
  check('estagiário/PJ sem férias CLT: 422', (await call(hr, 'POST', '/edu/rh/ferias/programacoes', { colaboradorId: id5, periodoId: per2, parcelas: [{ inicio: '2026-12-01', dias: 14 }] })).status === 422)

  secao('Carreira, bonificações e advertências')
  const plano = (await call(hr, 'POST', '/edu/rh/planos-carreira', { nome: 'Plano Técnico-Administrativo' })).json
  const n1 = await call(hr, 'POST', `/edu/rh/planos-carreira/${plano.id}/niveis`, { ordem: 1, nome: 'Assistente I', salarioBase: 3000, intersticioMeses: 12 })
